import { useQuery } from '@tanstack/react-query'
import { Plus } from 'lucide-react'
import { templatesService } from '@/integrations/supabase/templates'
import { useTenant } from '@/app/providers/TenantProvider'

export function TemplatesAdminPage() {
  const { manifest } = useTenant()
  const { data: templates = [], isLoading } = useQuery({
    queryKey: ['templates', manifest?.tenantId],
    queryFn: () => templatesService.listTemplates(manifest?.tenantId),
  })

  return (
    <div className="h-full overflow-y-auto p-6">
      <div className="max-w-4xl mx-auto">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h2 className="font-semibold">Templates</h2>
            <p className="text-sm text-muted-foreground">Manage project templates available to your tenant</p>
          </div>
          <button className="flex items-center gap-1.5 text-sm bg-accent text-accent-foreground px-3 py-1.5 rounded-lg hover:opacity-90">
            <Plus size={14} /> New template
          </button>
        </div>
        {isLoading ? (
          <p className="text-sm text-muted-foreground">Loading…</p>
        ) : templates.length === 0 ? (
          <div className="rounded-xl border border-dashed border-border p-10 text-center">
            <p className="text-sm text-muted-foreground">No templates yet</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            {templates.map((t) => (
              <div key={t.id} className="bg-surface rounded-xl border border-border p-4">
                <div className="flex items-start justify-between">
                  <div>
                    <p className="font-medium text-sm">{t.title}</p>
                    <p className="text-xs text-muted-foreground mt-1">{t.description}</p>
                  </div>
                  <span className={`text-xs px-2 py-0.5 rounded-full ${t.type === 'public' ? 'bg-success/10 text-success' : t.type === 'paid' ? 'bg-warning/10 text-warning' : 'bg-muted'}`}>{t.type}</span>
                </div>
                <p className="text-xs text-muted-foreground mt-3">{t.objectivesCount} objectives</p>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}
